contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address who, uint256 lockTime, uint256 putAmount, uint256 collectAmount) public payable {
        require(putAmount > 0, "putAmount must be positive");
        require(address(this).balance >= putAmount, "test must be funded");

        // Setup: initialise the contract so MinSum can be set and Put/Collect can run.
        c.SetMinSum(0);
        c.Initialized();

        // Record the holder's starting balance through the public getter of Acc.
        (uint256 unlockBefore, uint256 balBefore) = c.Acc(who);

        // Send Ether into the contract through Put on behalf of `who`.
        c.Put{value: putAmount}(lockTime);

        // Read what Put recorded for the holder.
        (uint256 unlockAfterPut, uint256 balAfterPut) = c.Acc(who);

        // Attempt a Collect of collectAmount from `who`'s holder balance.
        // The call may revert or may itself fail, so it is wrapped in a try/catch;
        // the deciding call is still a top-level statement.
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Final holder balance observed through the public getter.
        (uint256 unlockAfterCollect, uint256 balAfterCollect) = c.Acc(who);

        // General rule: Put must credit the holder's balance by exactly the sent value,
        // and any subsequent successful Collect must leave a balance that is not greater
        // than before (it can only stay the same or decrease). The holder's stored unlock
        // time cannot be earlier than the timestamp when Put ran.
        assert(balAfterPut == balBefore + putAmount);
        assert(balAfterCollect <= balAfterPut);
        assert(unlockAfterPut >= block.timestamp || unlockAfterPut == unlockBefore);
    }

    receive() external payable {}
}

