contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint lockTime, uint deposit, uint collectAmt) public payable {
        require(address(this).balance >= deposit);

        // Set MinSum to 0 so the lock condition depends only on unlockTime
        c.SetMinSum(0);
        c.Initialized();

        // Deposit Ether and set a lock time
        c.Put{value: deposit}(lockTime);

        // Read the caller's account state
        (uint unlockTimeBefore, uint balanceBefore) = c.Acc(address(this));
        uint contractBefore = address(c).balance;

        // Attempt to collect
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after state
        (, uint balanceAfter) = c.Acc(address(this));
        uint contractAfter = address(c).balance;

        // Rule: if the call succeeds, the account balance decreased by exactly collectAmt
        // and the contract balance decreased by exactly collectAmt
        assert(reverted || (balanceBefore - balanceAfter == collectAmt && contractBefore - contractAfter == collectAmt));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint lockTime, uint deposit, uint collectAmt) public payable {
        require(address(this).balance >= deposit);

        // Initialize with a MinSum that we can vary via parameter? MinSum is public, but only before Initialized.
        // We call SetMinSum with a parameter to control threshold. Use collectAmt as a simple threshold?
        // To avoid the add_uint256 overflow in Put, we only call Put with lockTime that does not overflow.
        require(lockTime <= block.timestamp + 100000); // safe zone for add_uint256

        c.SetMinSum(0); // no minimum balance requirement for Collect
        c.Initialized();

        // Deposit: this calls Put which adds msg.value to balance and updates unlockTime with add_uint256(block.timestamp, lockTime)
        c.Put{value: deposit}(lockTime);

        // Read before-state for our account and contract ether
        (uint unlockTimeBefore, uint balanceBefore) = c.Acc(address(this));
        uint contractBefore = address(c).balance;

        // Record if Collect reverts (should not under normal conditions, but if it does we assert the no-op case)
        bool collectReverted;
        try c.Collect(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after-state
        (uint unlockTimeAfter, uint balanceAfter) = c.Acc(address(this));
        uint contractAfter = address(c).balance;

        // General rule: Collect either succeeds and moves exactly collectAmt from account to caller,
        // or it does nothing (no state change). Reverting is also equivalent to doing nothing
        // (since the state reverts), but we capture the revert flag and treat it as no-op.
        // To avoid subtraction underflow, we use addition.
        bool noChange = (balanceAfter == balanceBefore && contractAfter == contractBefore);
        bool exactTransfer = (balanceAfter + collectAmt == balanceBefore && contractAfter + collectAmt == contractBefore);

        // If collectReverted, then the state must be unchanged (revert reverts all changes).
        // If not reverted, then either the collect moved exactly collectAmt or it did nothing.
        // But note: if collectAmt is zero, then exactTransfer and noChange may overlap; that's fine.
        assert( (collectReverted && noChange) || (!collectReverted && (noChange || exactTransfer)) );
    }

    receive() external payable {}
}

